// Package server implements the kvhttp HTTP API on top of a store.Store.
package server

import (
	"encoding/json"
	"errors"
	"io"
	"log/slog"
	"net/http"
	"strconv"
	"strings"

	"kvhttp/internal/store"
)

// MaxValueSize is the largest value, in bytes, accepted by PUT /kv/<key>.
const MaxValueSize = 1 << 20

const maxKeyLen = 64

// Handler serves the kvhttp routes. It routes on the raw request path itself
// rather than using http.ServeMux, so that unclean paths (e.g. "/kv/a/../b")
// are rejected as invalid keys instead of being redirected.
type Handler struct {
	store *store.Store
}

// New returns a Handler backed by s.
func New(s *store.Store) *Handler {
	return &Handler{store: s}
}

func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	path := r.URL.Path
	switch {
	case path == "/health":
		if !allow(w, r, http.MethodGet) {
			return
		}
		writeBody(w, http.StatusOK, "text/plain; charset=utf-8", []byte("ok"))
	case path == "/kv":
		if !allow(w, r, http.MethodGet) {
			return
		}
		h.list(w)
	case strings.HasPrefix(path, "/kv/"):
		h.item(w, r, strings.TrimPrefix(path, "/kv/"))
	default:
		http.NotFound(w, r)
	}
}

func (h *Handler) list(w http.ResponseWriter) {
	body, err := json.Marshal(h.store.Keys())
	if err != nil {
		slog.Error("encode key list", "err", err)
		http.Error(w, http.StatusText(http.StatusInternalServerError), http.StatusInternalServerError)
		return
	}
	writeBody(w, http.StatusOK, "application/json", body)
}

func (h *Handler) item(w http.ResponseWriter, r *http.Request, key string) {
	if !allow(w, r, http.MethodGet, http.MethodPut, http.MethodDelete) {
		return
	}
	if !validKey(key) {
		http.Error(w, "invalid key", http.StatusBadRequest)
		return
	}

	switch r.Method {
	case http.MethodGet:
		v, ok := h.store.Get(key)
		if !ok {
			http.NotFound(w, r)
			return
		}
		writeBody(w, http.StatusOK, "application/octet-stream", v)
	case http.MethodPut:
		value, err := readValue(w, r)
		if err != nil {
			if _, ok := errors.AsType[*http.MaxBytesError](err); ok {
				http.Error(w, "value too large", http.StatusRequestEntityTooLarge)
				return
			}
			http.Error(w, "read body", http.StatusBadRequest)
			return
		}
		status := http.StatusOK
		if h.store.Put(key, value) {
			status = http.StatusCreated
		}
		w.Header().Set("Content-Length", "0")
		w.WriteHeader(status)
	case http.MethodDelete:
		if !h.store.Delete(key) {
			http.NotFound(w, r)
			return
		}
		w.WriteHeader(http.StatusNoContent)
	}
}

// readValue reads the full request body, enforcing MaxValueSize.
func readValue(w http.ResponseWriter, r *http.Request) ([]byte, error) {
	body := http.MaxBytesReader(w, r.Body, MaxValueSize)
	if r.ContentLength > MaxValueSize {
		return nil, &http.MaxBytesError{Limit: MaxValueSize}
	}
	if r.ContentLength >= 0 {
		buf := make([]byte, r.ContentLength)
		if _, err := io.ReadFull(body, buf); err != nil {
			return nil, err
		}
		return buf, nil
	}
	return io.ReadAll(body)
}

// allow reports whether r.Method is one of methods. If not, it writes a 405
// response with an Allow header and returns false.
func allow(w http.ResponseWriter, r *http.Request, methods ...string) bool {
	for _, m := range methods {
		if r.Method == m {
			return true
		}
	}
	w.Header().Set("Allow", strings.Join(methods, ", "))
	http.Error(w, http.StatusText(http.StatusMethodNotAllowed), http.StatusMethodNotAllowed)
	return false
}

func writeBody(w http.ResponseWriter, status int, contentType string, body []byte) {
	w.Header().Set("Content-Type", contentType)
	w.Header().Set("Content-Length", strconv.Itoa(len(body)))
	w.WriteHeader(status)
	if _, err := w.Write(body); err != nil {
		slog.Debug("write response", "err", err)
	}
}

// validKey reports whether key matches [A-Za-z0-9_-]{1,64}.
func validKey(key string) bool {
	if len(key) == 0 || len(key) > maxKeyLen {
		return false
	}
	for i := range len(key) {
		c := key[i]
		switch {
		case 'a' <= c && c <= 'z', 'A' <= c && c <= 'Z', '0' <= c && c <= '9', c == '_', c == '-':
		default:
			return false
		}
	}
	return true
}

package server

import (
	"bytes"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"testing"

	"kvhttp/internal/store"
)

func do(t *testing.T, h http.Handler, method, path string, body []byte) *httptest.ResponseRecorder {
	t.Helper()
	req := httptest.NewRequest(method, path, bytes.NewReader(body))
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	return rec
}

func TestRoutes(t *testing.T) {
	t.Parallel()
	h := New(store.New())
	long := strings.Repeat("k", 64)
	steps := []struct {
		method, path, body string
		status             int
		want               string
	}{
		{"GET", "/health", "", 200, "ok"},
		{"POST", "/health", "", 405, ""},
		{"GET", "/health/", "", 404, ""},
		{"GET", "/", "", 404, ""},
		{"GET", "/kv", "", 200, "[]"},
		{"PUT", "/kv", "", 405, ""},
		{"PUT", "/kv/b", "2", 201, ""},
		{"PUT", "/kv/" + long, "x", 201, ""},
		{"PUT", "/kv/" + long + "k", "x", 400, ""},
		{"PUT", "/kv/A-_9", "", 201, ""},
		{"GET", "/kv/A-_9", "", 200, ""},
		{"PUT", "/kv/b", "22", 200, ""},
		{"GET", "/kv/b", "", 200, "22"},
		{"GET", "/kv", "", 200, `["A-_9","b","` + long + `"]`},
		{"GET", "/kv/", "", 400, ""},
		{"GET", "/kv/a/b", "", 400, ""},
		{"GET", "/kv/a.b", "", 400, ""},
		{"PATCH", "/kv/b", "", 405, ""},
		{"DELETE", "/kv/b", "", 204, ""},
		{"DELETE", "/kv/b", "", 404, ""},
		{"GET", "/kv/b", "", 404, ""},
	}
	for _, s := range steps {
		rec := do(t, h, s.method, s.path, []byte(s.body))
		if rec.Code != s.status {
			t.Fatalf("%s %s: status %d, want %d", s.method, s.path, rec.Code, s.status)
		}
		if s.want != "" && rec.Body.String() != s.want {
			t.Fatalf("%s %s: body %q, want %q", s.method, s.path, rec.Body.String(), s.want)
		}
	}
}

func TestValueSize(t *testing.T) {
	t.Parallel()
	h := New(store.New())
	max := bytes.Repeat([]byte{0xff}, MaxValueSize)
	if rec := do(t, h, "PUT", "/kv/big", max); rec.Code != http.StatusCreated {
		t.Fatalf("PUT 1 MiB: status %d", rec.Code)
	}
	if rec := do(t, h, "GET", "/kv/big", nil); !bytes.Equal(rec.Body.Bytes(), max) {
		t.Fatalf("GET 1 MiB: body differs (%d bytes)", rec.Body.Len())
	}
	if rec := do(t, h, "PUT", "/kv/big", append(max, 0)); rec.Code != http.StatusRequestEntityTooLarge {
		t.Fatalf("PUT 1 MiB + 1: status %d", rec.Code)
	}
}

func TestConcurrentPuts(t *testing.T) {
	t.Parallel()
	h := New(store.New())
	var wg sync.WaitGroup
	for i := range 64 {
		wg.Go(func() {
			do(t, h, "PUT", "/kv/k"+strings.Repeat("x", i), []byte("v"))
		})
	}
	wg.Wait()
	if got := len(h.store.Keys()); got != 64 {
		t.Fatalf("keys = %d, want 64", got)
	}
}

// Package store provides a concurrency-safe in-memory key-value store.
package store

import (
	"maps"
	"slices"
	"sync"
)

// Store is an in-memory map of keys to byte values, safe for concurrent use.
// The zero value is not usable; create one with New.
type Store struct {
	mu   sync.RWMutex
	data map[string][]byte
}

// New returns an empty Store.
func New() *Store {
	return &Store{data: make(map[string][]byte)}
}

// Get returns the value stored under key and whether it was present.
// The returned slice must not be modified.
func (s *Store) Get(key string) ([]byte, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	v, ok := s.data[key]
	return v, ok
}

// Put stores value under key and reports whether the key was newly created.
// The store takes ownership of value; callers must not modify it afterwards.
func (s *Store) Put(key string, value []byte) (created bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, existed := s.data[key]
	s.data[key] = value
	return !existed
}

// Delete removes key and reports whether it was present.
func (s *Store) Delete(key string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, ok := s.data[key]
	if ok {
		delete(s.data, key)
	}
	return ok
}

// Keys returns every key in ascending order. It never returns nil.
func (s *Store) Keys() []string {
	s.mu.RLock()
	keys := make([]string, 0, len(s.data))
	keys = slices.AppendSeq(keys, maps.Keys(s.data))
	s.mu.RUnlock()
	slices.Sort(keys)
	return keys
}

// Command app runs the kvhttp in-memory key-value HTTP server.
//
// Usage:
//
//	app <port>
package main

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"

	"kvhttp/internal/server"
	"kvhttp/internal/store"
)

func main() {
	if err := run(os.Args[1:]); err != nil {
		fmt.Fprintln(os.Stderr, "app:", err)
		os.Exit(1)
	}
}

func run(args []string) error {
	if len(args) != 1 {
		return errors.New("usage: app <port>")
	}
	port, err := strconv.ParseUint(args[0], 10, 16)
	if err != nil {
		return fmt.Errorf("invalid port %q: %w", args[0], err)
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	addr := net.JoinHostPort("127.0.0.1", strconv.FormatUint(port, 10))
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		return fmt.Errorf("listen: %w", err)
	}

	srv := &http.Server{
		Handler:           server.New(store.New()),
		ReadHeaderTimeout: 10 * time.Second,
		ReadTimeout:       60 * time.Second,
		WriteTimeout:      60 * time.Second,
		IdleTimeout:       120 * time.Second,
		MaxHeaderBytes:    1 << 20,
	}

	errc := make(chan error, 1)
	go func() { errc <- srv.Serve(ln) }()
	slog.Info("listening", "addr", addr)

	select {
	case err := <-errc:
		return fmt.Errorf("serve: %w", err)
	case <-ctx.Done():
	}

	sctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := srv.Shutdown(sctx); err != nil {
		return fmt.Errorf("shutdown: %w", err)
	}
	return nil
}
